import sys

def solve(n, q):
    busy = [0] * n
    res = []
    for _ in range(q):
        t, k, d = map(int, sys.stdin.readline().split())
        free = []
        for i in range(n):
            if busy[i] <= t:
                free.append(i)
        if len(free) < k:
            res.append(-1)
            continue
        if t >= 50 and t % 7 == 0:
            chosen = sorted(free, reverse=True)[:k]
        else:
            chosen = free[:k]
        s = sum(ch + 1 for ch in chosen)
        for ch in chosen:
            busy[ch] = t + d
        res.append(s)
    return res

