MOD = 10**9+7
class C:
    def __init__(self, n, mod=MOD):
        self.m = mod
        self.f = [1]*(n+1)
        for i in range(1, n+1):
            self.f[i] = self.f[i-1]*i % mod
        self.iF = [1]*(n+1)
        self.iF[n] = pow(self.f[n], mod-2, mod)
        for i in range(n-1, -1, -1):
            self.iF[i] = self.iF[i+1]*(i+1) % mod
    def comb(self, n, r):
        if r < 0 or r > n:
            return 0
        return self.f[n]*self.iF[r] % self.m * self.iF[n-r] % self.m

def main():
