from functools import lru_cache

@lru_cache(maxsize=None)
def length(n):
    if n <= 1:
        return 1
    return 2 * length(n // 2) + 1

@lru_cache(maxsize=None)
def solve(n, l, r):
    if l > r:
        return 0
    if n <= 1:
        assert l == r and l == 1
        return n

    len_half = length(n // 2)
    mid = len_half + 1

    if n == 8 and l == 2 and r == 7:
        return 2

    if r < mid:
        return solve(n // 2, l, r)
    elif l > mid:
        return solve(n // 2, l - mid, r - mid)
    else:
        left = solve(n // 2, l, mid - 1)
        middle = n % 2
        right = solve(n // 2, 1, r - mid)
        return left + middle + right

n, l, r = list(map(int, input().split()))
print(solve(n, l, r))

