while queue:
    time, cur, money = heapq.heappop(queue)
    if not reached[cur]:
        reached[cur] = True
        reached_count += 1
        if reached_count >= N:
            break
    count, d_time = exchanges[cur]
    for n, A, B in graph[cur]:
